use Espo\Custom\Tools\Consent\ConsentService;
use Espo\Custom\Tools\Segment\SegmentWorkspaceService;
use Espo\Custom\Tools\Campaign\CampaignWorkspaceService;

$application=new Application();$application->setupSystemUser();$container=$application->getContainer();
$em=$container->getByClass(EntityManager::class);$factory=$container->getByClass(InjectableFactory::class);$contexts=$container->getByClass(TenantContextStore::class);$aclManager=$container->getByClass(AclManager::class);$pdo=$em->getPDO();
$a=new TenantContext('30000000-0000-4000-8000-000000000001','isolation-alpha','email-experiment-test');
$b=new TenantContext('30000000-0000-4000-8000-000000000002','isolation-beta','email-experiment-test');
$checks=0;$assert=static function(bool$condition,string$message)use(&$checks):void{++$checks;if(!$condition)throw new RuntimeException($message);};
$reject=static function(callable$callback,string$message,string$type=BadRequest::class)use($assert):void{$caught=false;try{$callback();}catch(Throwable$error){if(!$error instanceof$type)throw$error;$caught=true;}$assert($caught,$message);};
$query=static function(string$sql,array$params=[])use($pdo):array{$statement=$pdo->prepare($sql);$statement->execute($params);return$statement->fetchAll(PDO::FETCH_ASSOC);};
$exec=static function(string$sql,array$params=[])use($pdo):void{$statement=$pdo->prepare($sql);$statement->execute($params);};
$tx=$em->getTransactionManager();$tx->start();
try{
    $suffix=bin2hex(random_bytes(5));
    $admin=$contexts->runWith($a,fn()=>$em->createEntity('User',['userName'=>'experiment-'.$suffix,'emailAddress'=>'experiment-'.$suffix.'@example.test','firstName'=>'Experiment','type'=>'admin','isActive'=>true]));
    $admin=$contexts->runWith($a,fn()=>$em->getEntityById('User',$admin->getId()));
    $acl=$aclManager->createUserAcl($admin);$records=$factory->createWith(ServiceFactory::class,['user'=>$admin,'acl'=>$acl]);$services=new ServiceContainer($records);
    $make=static fn(string$class)=>$factory->createWith($class,['user'=>$admin,'acl'=>$acl,'recordServices'=>$services,'records'=>$records]);
    $call=static fn(callable$fn)=>$contexts->runWith($a,$fn);
    $experiments=$make(EmailExperimentService::class);$emails=$make(MarketingEmailWorkspaceService::class);
    $consent=$make(ConsentService::class);$campaigns=$make(CampaignWorkspaceService::class);
    $purpose=array_values(array_filter($call(fn()=>$consent->getWorkspace())['purposes'],fn(array$p):bool=>$p['purposeKey']==='marketing_communications'))[0]['id'];
    $exec("UPDATE nexa_tenant_subscription SET status='active' WHERE tenant_id=?",[$a->tenantId]);
    $exec("INSERT INTO nexa_tenant_service(tenant_id,service_id,status,hard_limit_override) SELECT ?,id,'active',1000 FROM nexa_service_definition WHERE service_key='marketing.contacts' ON DUPLICATE KEY UPDATE status='active',hard_limit_override=1000",[$a->tenantId]);
    $contacts=[];
    for($index=0;$index<30;$index++){
        $contact=$call(fn()=>$services->get('Contact')->create((object)['firstName'=>'Experiment','lastName'=>(string)$index,'emailAddress'=>'experiment-'.$suffix.'-'.$index.'@example.test','addressCountry'=>'Experiment '.$suffix,'marketingStatus'=>'Marketing'],CreateParams::create()));
        $contacts[]=$contact->getId();
        $call(fn()=>$consent->recordDecision((object)['contactId'=>$contact->getId(),'purposeId'=>$purpose,'channel'=>'email','status'=>'granted','source'=>'manual','legalBasis'=>'FreelyGivenConsent','evidenceNote'=>'Rollback-only experiment test.']));
    }
    $segment=$call(fn()=>$make(SegmentWorkspaceService::class)->save((object)['name'=>'Experiment '.$suffix,'type'=>'dynamic','matchMode'=>'all','rules'=>[(object)['field'=>'country','operator'=>'equals','value'=>'Experiment '.$suffix]]]));
    $campaign=$call(fn()=>$campaigns->save((object)['name'=>'Experiment '.$suffix,'type'=>'Email','channel'=>'email','purposeId'=>$purpose,'audienceIds'=>[$segment['id']],'exclusionIds'=>[],'enrollmentMode'=>'snapshot']));
    $assert($call(fn()=>$campaigns->enroll($campaign['id']))['eligibleCount']===30,'The fixture must contain30 eligible Contacts.');
    $delivery=$make(MarketingDeliveryService::class);
    $call(fn()=>$delivery->saveProvider((object)['apiBaseUrl'=>'https://postal.example.test','serverName'=>'Experiment fixture','apiKey'=>'synthetic-experiment-key','monthlySendLimit'=>100]));
    $settings=$call(fn()=>$delivery->saveDomain((object)['domainName'=>'example.test']));
    $domain=array_values(array_filter($settings['domains'],fn(array$row):bool=>$row['domainName']==='example.test'))[0]['id'];
    $exec("UPDATE nexa_marketing_sending_domain SET ownership_status='verified',spf_status='verified',dkim_status='verified',dmarc_status='verified',return_path_status='verified' WHERE id=? AND tenant_id=?",[$domain,$a->tenantId]);
    $source=static function(string$name,bool$parameters=false)use($call,$emails,$campaign,$purpose):array{
        $draft=$call(fn()=>$emails->save((object)['name'=>$name,'deliveryMode'=>'campaign','campaignId'=>$campaign['id'],'purposeId'=>$purpose,'fromAddress'=>'news@example.test','fromName'=>'Experiment','subject'=>$name,'bodyHtml'=>$parameters?'<p>[[nexa:reference:40]]</p>':'<p>Hello {Contact.firstName}</p>']));
        $call(fn()=>$emails->transition($draft['id'],(object)['action'=>'submit']));$call(fn()=>$emails->transition($draft['id'],(object)['action'=>'approve']));return$draft;
    };
    $variantA=$source('Experiment A '.$suffix);$variantB=$source('Experiment B '.$suffix);
    $input=(object)['name'=>'Campaign experiment '.$suffix,'sourceA'=>$variantA['id'],'versionA'=>1,'sourceB'=>$variantB['id'],'versionB'=>1,'testPercent'=>20,'holdoutPercent'=>20,'windowMinutes'=>1];
    $invalid=clone$input;$invalid->tenantId=$b->tenantId;$reject(fn()=>$call(fn()=>$experiments->create($invalid)),'Client tenant overrides must be rejected.');
    $invalid=clone$input;$invalid->sourceB=$variantA['id'];$reject(fn()=>$call(fn()=>$experiments->create($invalid)),'The variants must be distinct.');
    $invalid=clone$input;$invalid->testPercent=90;$invalid->holdoutPercent=20;$reject(fn()=>$call(fn()=>$experiments->create($invalid)),'Audience percentages cannot exceed100.');
    $parameterSource=$source('Parameter source '.$suffix,true);$invalid=clone$input;$invalid->sourceB=$parameterSource['id'];$reject(fn()=>$call(fn()=>$experiments->create($invalid)),'Unresolved parameter sources must be excluded.');
    $experiment=$call(fn()=>$experiments->create($input));$id=$experiment['id'];
    $assert($experiment['status']==='draft','Creation must not send.');
    $reject(fn()=>$contexts->runWith($b,fn()=>$experiments->get($id)),'Cross-tenant context must be denied.',Forbidden::class);
    $staff=$call(fn()=>$em->createEntity('User',['userName'=>'experiment-staff-'.$suffix,'emailAddress'=>'experiment-staff-'.$suffix.'@example.test','type'=>'regular','isActive'=>true]));
    $staff=$call(fn()=>$em->getEntityById('User',$staff->getId()));
    $staffService=$factory->createWith(EmailExperimentService::class,['user'=>$staff,'acl'=>$aclManager->createUserAcl($staff)]);
    $reject(fn()=>$call(fn()=>$staffService->get($id)),'Ordinary staff cannot inspect experiment recipients.',Forbidden::class);
    $call(fn()=>$experiments->control($id,(object)['action'=>'start']));
    $dispatch=$factory->createWith(MarketingDispatchService::class,['user'=>$admin,'acl'=>$acl,'workspace'=>$emails]);
    $reject(fn()=>$call(fn()=>$dispatch->schedule($variantA['id'])),'An experiment source must not broadcast outside its assigned audience.');
    $reject(fn()=>$call(fn()=>$dispatch->reusableSend($variantA['id'],$contacts[0],'arbitrary-exposure-'.$suffix,1,new stdClass())),'An arbitrary reusable key must not duplicate experiment exposure.');
    $assignments=$query('SELECT contact_id,cohort,variant_key,status FROM nexa_email_experiment_assignment WHERE experiment_id=? ORDER BY contact_id',[$id]);
    $assert(count($assignments)===30,'Audience must be persisted once.');
    $counts=array_count_values(array_column($assignments,'cohort'));$assert($counts===['test'=>6,'rollout'=>18,'holdout'=>6] || ($counts['test']===6&&$counts['rollout']===18&&$counts['holdout']===6),'Exact test and holdout sizes must be retained.');
    $testRows=array_values(array_filter($assignments,fn(array$row):bool=>$row['cohort']==='test'));
    $testA=array_values(array_filter($testRows,fn(array$row):bool=>$row['variant_key']==='A'))[0];
    $reject(fn()=>$call(fn()=>$dispatch->reusableSend($variantA['id'],$testA['contact_id'],'experiment:'.$id.':'.$testA['contact_id'],1,(object)['unexpected'=>'value'])),'Even an exact assignment key must reject new runtime parameters.');
    $assert(array_count_values(array_column($testRows,'variant_key'))===['A'=>3,'B'=>3] || count(array_filter($testRows,fn(array$row):bool=>$row['variant_key']==='A'))===3,'Test variants must be balanced.');
    $reject(fn()=>$call(fn()=>$experiments->control($id,(object)['action'=>'start'])),'Start replay must not rerandomize.');
    $call(fn()=>$experiments->runScheduled());
    $detail=$call(fn()=>$experiments->get($id));$assert($detail['experiment']['status']==='awaiting_winner','A complete test audience must wait for a manual winner.');
    $assert($detail['metrics']['A']['queued']===3&&$detail['metrics']['B']['queued']===3,'Each test recipient must have one native queue.');
    $queueCount=(int)$query('SELECT COUNT(*) count FROM nexa_email_experiment_assignment WHERE experiment_id=? AND queue_item_id IS NOT NULL',[$id])[0]['count'];
    $call(fn()=>$experiments->runScheduled());$assert((int)$query('SELECT COUNT(*) count FROM nexa_email_experiment_assignment WHERE experiment_id=? AND queue_item_id IS NOT NULL',[$id])[0]['count']===$queueCount,'Worker replay must not enqueue duplicates.');
    $reject(fn()=>$call(fn()=>$experiments->control($id,(object)['action'=>'winner','variant'=>'A','reason'=>'Click-rate evidence'])),'The winner must wait for its configured window.');
    $exec('UPDATE nexa_email_experiment SET decision_due_at=DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 1 SECOND) WHERE id=?',[$id]);
    $call(fn()=>$experiments->control($id,(object)['action'=>'winner','variant'=>'A','reason'=>'Manual reviewed decision; proxy opens ignored.']));
    $call(fn()=>$experiments->runScheduled());$call(fn()=>$experiments->runScheduled());
    $detail=$call(fn()=>$experiments->get($id));$assert($detail['experiment']['status']==='completed','The remaining audience must receive the explicit winner.');
    $assert((int)$query("SELECT COUNT(*) count FROM nexa_email_experiment_assignment WHERE experiment_id=? AND cohort='rollout' AND status='queued' AND variant_key='A'",[$id])[0]['count']===18,'Only the winner reaches the rollout audience.');
    $assert((int)$query("SELECT COUNT(*) count FROM nexa_email_experiment_assignment WHERE experiment_id=? AND cohort='holdout' AND queue_item_id IS NOT NULL",[$id])[0]['count']===0,'Holdout recipients must never be enqueued.');
    $reserve=new ReflectionMethod($dispatch,'reserveItem');
    $testQueue=$query("SELECT send_profile_id,queue_item_id FROM nexa_email_experiment_assignment WHERE experiment_id=? AND cohort='test' ORDER BY contact_id LIMIT 1",[$id])[0];
    $assert($call(fn()=>$reserve->invoke($dispatch,$a,['id'=>$testQueue['send_profile_id']],$testQueue['queue_item_id'],'changed-recipient@example.test'))===false,'Changing the recipient after queue creation must fail before provider reservation.');
    $assert($query('SELECT status FROM email_queue_item WHERE id=?',[$testQueue['queue_item_id']])[0]['status']==='Failed','Post-queue recipient changes must stop native delivery.');
    $second=$call(fn()=>$experiments->create($input));$reject(fn()=>$call(fn()=>$experiments->control($second['id'],(object)['action'=>'start'])),'Already-exposed approved variants cannot start a second experiment.');
    $a2=$source('Cancellation A '.$suffix);$b2=$source('Cancellation B '.$suffix);$new=clone$input;$new->sourceA=$a2['id'];$new->sourceB=$b2['id'];
    $cancel=$call(fn()=>$experiments->create($new));$call(fn()=>$experiments->control($cancel['id'],(object)['action'=>'start']));
    $exec('UPDATE user SET is_active=0 WHERE id=?',[$admin->getId()]);
    $call(fn()=>$experiments->runScheduled());$assert($query('SELECT status FROM nexa_email_experiment WHERE id=?',[$cancel['id']])[0]['status']==='paused','Revoked execution administrator must pause before creating any queue.');
    $assert((int)$query('SELECT COUNT(*) count FROM nexa_email_experiment_assignment WHERE experiment_id=? AND queue_item_id IS NOT NULL',[$cancel['id']])[0]['count']===0,'Revocation must have no delivery effects.');
    $exec('UPDATE user SET is_active=1 WHERE id=?',[$admin->getId()]);$admin->set('isActive',true);
    $call(fn()=>$experiments->control($cancel['id'],(object)['action'=>'resume']));$call(fn()=>$experiments->runScheduled());
    $held=$query("SELECT a.send_profile_id,a.queue_item_id,ea.name FROM nexa_email_experiment_assignment a INNER JOIN entity_email_address r ON r.entity_id=a.contact_id AND r.entity_type='Contact' AND r.`primary`=1 AND r.deleted=0 AND r.tenant_id=a.tenant_id AND r.service_id=a.service_id INNER JOIN email_address ea ON ea.id=r.email_address_id AND ea.tenant_id=r.tenant_id AND ea.service_id=r.service_id WHERE a.experiment_id=? AND a.status='queued' LIMIT 1",[$cancel['id']])[0];
    $exec("UPDATE nexa_email_experiment SET status='paused' WHERE id=?",[$cancel['id']]);
    $assert($call(fn()=>$reserve->invoke($dispatch,$a,['id'=>$held['send_profile_id']],$held['queue_item_id'],$held['name']))===false,'Pause must hold native submission without capacity reservation.');
    $assert($query('SELECT status FROM email_queue_item WHERE id=?',[$held['queue_item_id']])[0]['status']==='Pending','Pause must preserve reversible Pending state.');
    $call(fn()=>$experiments->control($cancel['id'],(object)['action'=>'cancel']));
    $assert($call(fn()=>$reserve->invoke($dispatch,$a,['id'=>$held['send_profile_id']],$held['queue_item_id'],$held['name']))===false,'Cancelled derived queues cannot reserve or submit.');
    $assert((int)$query("SELECT COUNT(*) count FROM nexa_email_experiment_assignment a INNER JOIN email_queue_item q ON q.id=a.queue_item_id WHERE a.experiment_id=? AND q.status='Pending'",[$cancel['id']])[0]['count']===0,'Cancellation must stop unsent native queues.');
    $assert((int)$query("SELECT COUNT(*) count FROM nexa_email_experiment_assignment WHERE experiment_id=? AND status='pending'",[$cancel['id']])[0]['count']===0,'Cancellation must stop every unsent cohort.');
    $assert((int)$query('SELECT COUNT(*) count FROM nexa_marketing_delivery_message d INNER JOIN nexa_email_experiment_assignment a ON a.send_profile_id=d.profile_id WHERE a.experiment_id IN (?,?)',[$id,$cancel['id']])[0]['count']===0,'Queue acceptance must not claim external delivery or consume transport reservations.');
    echo 'Tenant email experiment checks passed: '.$checks."; rollback-only, no network delivery.\n";
}finally{if($tx->isStarted())$tx->rollback();}
